includeIf.script:
// runs right away rather than on document ready: #preg-group-current is already above this script, and an error
// in another form's ready handler (e.g. Simple UI-only code) would stop later ready handlers from running
(function() {
    const contextPath = window.location.href.split('/')[3];
    const pregnancyProgramUuid = '${program.pregnancy.uuid}';
    const patientUuid = '';
    const pregGroupObsTime = +'';
    // the date the enrollment must be active on: the encounter date when editing, else the visit start, else now
    const pregGroupCheckTime = +'';

    const startOfDay = function(time) { const d = new Date(time); d.setHours(0, 0, 0, 0); return d.getTime(); };
    const endOfDay = function(time) { const d = new Date(time); d.setHours(23, 59, 59, 999); return d.getTime(); };

    jq.getJSON('/' + contextPath + '/ws/rest/v1/programenrollment', {
        patient: patientUuid,
        v: 'custom:(program:(uuid),dateEnrolled,dateCompleted,voided)'
    }, function(data) {
        // show the group if it was recorded during a Pregnancy enrollment that is active on the check date
        // (compared by day, as enrollment dates may be entered without a time)
        const show = (data.results || []).some(function(pp) {
            if (pp.voided || !pp.program || pp.program.uuid !== pregnancyProgramUuid || !pp.dateEnrolled) {
                return false;
            }
            const enrolled = startOfDay(new Date(pp.dateEnrolled).getTime());
            const completed = pp.dateCompleted ? new Date(pp.dateCompleted).getTime() : null;
            const activeOnCheckDate = enrolled <= endOfDay(pregGroupCheckTime)
                && (completed === null || completed > pregGroupCheckTime);
            return activeOnCheckDate && pregGroupObsTime >= enrolled;
        });
        if (show) {
            jq('#preg-group-current').show();
        }
    });
})();
